        Stamp("deploy modules", OWNED, deploy_owned, _deploy_modules, staged_writer=True),

        Stamp("deploy modules", OWNED, deploy_owned, _deploy_modules, staged_writer=True),
        Stamp("acceptance harness", OWNED, (rel(ACCEPTANCE_SCRIPT_REL),), _acceptance, staged_writer=True),
